// LoansApplicationsSchema.js — FRONTEND schema: labels, formulas, remarks, click-throughs. Generated by gen-report.js from report.map (same folder).
// The numbers come from the backend twin app/api/mda4/reports/loans/applications/list/LoansApplicationsSchema.js (same measure keys).
import { getApiRoutes } from '../../../AppRoutes/apiRoutesHandler';
import LoansApplicationsActions from './logicControl/actionsRegistry';
const apiRoutes = getApiRoutes();

export const LoansApplicationsSchema = {
  entity: 'simukopa_loans_applications',
  label: 'Loan Applications',
  description: '',
  apiBase: apiRoutes.loansapplications?.base,
  moduleRole: 'view_reports',
  currency: 'KES',
  actionRegistry: LoansApplicationsActions,

  groupBy: 'month',
  groupLabel: 'Month',
  groupByOptions: [{ key: 'month', label: 'Month' }, { key: 'day', label: 'Day' }, { key: 'year', label: 'Year' }],

  fields: [
    { key: 'applied', label: 'Applications', from: 'loan_applications' },
    { key: 'approved', label: 'Approved', from: 'loan_applications' },
    { key: 'requested', label: 'Amount Requested', from: 'loan_applications.requested_amount', type: 'money' },
    { key: 'approved_value', label: 'Amount Approved', from: 'loan_applications.approved_amount', type: 'money' },
    { key: 'approval_rate', label: 'Approval %', calc: 'round(approved / applied * 100)' },
    { key: 'chg', label: 'Applied vs Previous', calc: 'change(applied)' },
  ],

  remarks: [
    { if: 'applied == 0', tone: 'watch', title: 'No applications', say: 'No loan applications were received in {label}.' },
    { if: 'approval_rate !== null && approval_rate < 50', tone: 'watch', title: 'Low approval', say: 'Only {approval_rate}% of the {applied} applications in {label} were approved.' },
    { if: 'true', tone: 'neutral', title: 'Applications', say: '{applied} applications, {approved} approved ({approval_rate}%), {approved_value} approved.' },
  ],

  headline: '{label}: {applied} applications, {approved} approved worth {approved_value}[, {updown} {abs(chg)}% on {prev_label}].',

  // coming periods the report page adds after the history (see forecast.js)
  forecast: [{ key: 'approved', next: 10, method: 'auto', integer: true }, { key: 'approved_value', next: 10, method: 'auto', integer: false }],
};
